// Files with one right answer. Condition 1 of the sync go decision (TECH-9825): generated files, migration numbers
// and profile digests are regenerated by their generators. The model never edits them, so every script here
// recognises them by path and either restores them (lockfiles), renumbers them (migrations) or runs the generator.
import { blobAt, gitOut, patchTree } from "./git.mjs";

const PR = "packages/paperclip-runner";

/**
 * Generators, in the order they must run (later ones read earlier outputs). `outputs` are the repo-relative paths
 * the generator writes; a conflict in any of them is settled by running `commands` from `cwd`, never by hand.
 * `pre` commands (a TypeScript build) must run first when `build: true`.
 */
export const GENERATORS = [
  {
    id: "app-definitions",
    cwd: ".",
    inputs: [/^packages\/shared\/src\/app-definitions\//, /^scripts\/ingest-app-definitions\.mjs$/],
    commands: [["node", "scripts/ingest-app-definitions.mjs", "--definitions-only"]],
    outputs: [
      /^packages\/shared\/src\/app-definitions\.generated\.ts$/,
      /^packages\/shared\/src\/app-definitions\.ingestion-report\.json$/,
    ],
  },
  {
    id: "acpx-profiles",
    cwd: PR,
    commands: [["node", "scripts/generate-acpx-profiles.mjs"]],
    outputs: [
      new RegExp(`^${PR}/src/drivers/acpx/generated-profiles\\.ts$`),
      new RegExp(`^${PR}/runner/crates/runner-core/src/generated_acpx_profiles\\.rs$`),
    ],
  },
  {
    id: "copilot-profile-identity",
    cwd: PR,
    commands: [["node", "scripts/copilot-profile-identity.mjs"]],
    outputs: [new RegExp(`^${PR}/test/fixtures/copilot-profile-v\\d+-identity\\.json$`)],
  },
  {
    id: "protocol-manifest",
    cwd: PR,
    commands: [["node", "scripts/generate-protocol-manifest.mjs"]],
    outputs: [new RegExp(`^${PR}/protocol/manifest\\.json$`)],
  },
  {
    id: "protocol-types",
    cwd: PR,
    commands: [
      ["node", "scripts/generate-protocol-schema-module.mjs"],
      ["node", "scripts/generate-acpx-sidecar-contract.mjs"],
    ],
    outputs: [
      new RegExp(`^${PR}/src/protocol/generated/`),
      new RegExp(`^${PR}/src/drivers/acpx/generated-sidecar-contract\\.ts$`),
      new RegExp(`^${PR}/runner/crates/runner-core/src/generated_acpx_sidecar_contract\\.rs$`),
    ],
  },
  {
    id: "capability-contract",
    cwd: PR,
    commands: [["node", "scripts/generate-capability-contract.mjs"]],
    outputs: [
      new RegExp(`^${PR}/generated/capability/(capabilities|mcp-tool-map|eval-traceability)\\.yaml$`),
      new RegExp(`^${PR}/generated/capability/(capability-contract|downstream-handoff)\\.md$`),
    ],
  },
  {
    id: "semantic-contracts",
    cwd: PR,
    build: true,
    commands: [["node", "scripts/generate-semantic-contracts.mjs"]],
    outputs: [
      new RegExp(`^${PR}/generated/capability/semantic-tool-contracts\\.json$`),
      new RegExp(`^${PR}/protocol/fixtures/evals/native-execution-seeded\\.json$`),
    ],
  },
  {
    id: "semantic-action-catalog",
    cwd: PR,
    build: true,
    commands: [["node", "scripts/generate-semantic-action-catalog.mjs"]],
    outputs: [new RegExp(`^${PR}/generated/semantic-action-catalog\\.json$`)],
  },
  {
    id: "protocol-coverage",
    cwd: PR,
    build: true,
    commands: [["node", "scripts/generate-protocol-coverage.mjs"]],
    outputs: [new RegExp(`^${PR}/spec/capability/protocol-coverage\\.json$`)],
  },
];

/** Did a change to any of these paths possibly make this generator's outputs stale? */
export function generatorIsAffected(generator, changedPaths) {
  const prefix = generator.cwd === "." ? null : `${generator.cwd}/`;
  return changedPaths.some(
    (p) =>
      (prefix && p.startsWith(prefix)) ||
      generator.outputs.some((re) => re.test(p)) ||
      (generator.inputs ?? []).some((re) => re.test(p)),
  );
}

export const BUILD_COMMAND = ["pnpm", "run", "build:typescript"];

export const LOCKFILE_RE = /(^|\/)(pnpm-lock\.yaml|package-lock\.json|yarn\.lock)$/;
export const MIGRATION_SQL_RE = /^packages\/db\/src\/migrations\/(\d{4})_([^/]+)\.sql$/;
export const MIGRATION_JOURNAL = "packages/db/src/migrations/meta/_journal.json";
export const MIGRATION_SNAPSHOT_RE = /^packages\/db\/src\/migrations\/meta\/(\d{4})_snapshot\.json$/;
// A generated file nobody registered yet. The model must not hand-edit it either; the report asks for a generator.
const GENERATED_HINT_RE = /(^|\/)generated\/|\.generated\.[a-z]+$|(^|\/)generated_[^/]+\.[a-z]+$/;

/** Classify one conflicted (or changed) path. Returns { kind: "real" } or { kind: "mechanical", rule, action, ... }. */
export function classifyFile(path) {
  if (LOCKFILE_RE.test(path)) return { kind: "mechanical", rule: "lockfile", action: "restore-master" };
  if (MIGRATION_SQL_RE.test(path)) return { kind: "mechanical", rule: "migration-sql", action: "renumber-migrations" };
  if (path === MIGRATION_JOURNAL) return { kind: "mechanical", rule: "migration-journal", action: "renumber-migrations" };
  if (MIGRATION_SNAPSHOT_RE.test(path)) {
    return { kind: "mechanical", rule: "migration-snapshot", action: "renumber-migrations" };
  }
  for (const generator of GENERATORS) {
    if (generator.outputs.some((re) => re.test(path))) {
      return { kind: "mechanical", rule: `generated:${generator.id}`, action: "regenerate", generator: generator.id };
    }
  }
  if (GENERATED_HINT_RE.test(path)) {
    return { kind: "mechanical", rule: "generated:unregistered", action: "needs-generator" };
  }
  return { kind: "real" };
}

export function classifyAll(paths) {
  return paths.map((path) => ({ path, ...classifyFile(path) }));
}

/** A path set the model must not edit by hand: every class except "real". */
export const isMechanicalPath = (path) => classifyFile(path).kind === "mechanical";

/** Split conflicted files into the ones a script settles and the ones left for the model. */
export function splitConflicts(paths) {
  const classified = classifyAll(paths);
  return {
    mechanical: classified.filter((c) => c.kind === "mechanical"),
    real: classified.filter((c) => c.kind === "real"),
  };
}

/**
 * Lockfiles never ride in a sync PR: the fork's `ci / policy` job rejects any PR that edits pnpm-lock.yaml
 * ("CI owns lockfile updates"). Put master's blob back for every lockfile the merge touched.
 */
export function restoreLockfiles(cwd, tree, masterRev) {
  const changed = gitOut(cwd, ["diff", "--name-only", "-z", masterRev, tree], { allowFail: true })
    .split("\0")
    .filter((p) => p && LOCKFILE_RE.test(p));
  if (changed.length === 0) return { tree, restored: [] };
  const changes = {};
  for (const path of changed) changes[path] = blobAt(cwd, masterRev, path);
  return { tree: patchTree(cwd, tree, changes), restored: changed };
}

/** Conflicts that settle without a work tree: lockfiles only. Anything else needs `start-conflict`. */
export function onlyLockfileConflicts(files) {
  return files.length > 0 && files.every((f) => LOCKFILE_RE.test(f));
}

